import hashlib
import hmac
import os
import time
import struct
import sqlite3
from contextlib import contextmanager

DB_PATH = os.environ.get('DB_PATH', ':memory:')
SESSION_SECRET = os.environ.get('SESSION_SECRET', os.urandom(32))
MAX_SESSION_AGE = 3600

PERM_READ = 0x01
PERM_WRITE = 0x02
PERM_DELETE = 0x04
PERM_ADMIN = 0x80000000  # Bit 31

def init_db():
    conn = sqlite3.connect(DB_PATH)
    conn.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        permissions INTEGER NOT NULL DEFAULT 1
    )''')
    conn.execute('''CREATE TABLE IF NOT EXISTS sessions (
        token_hash TEXT PRIMARY KEY,
        user_id INTEGER NOT NULL,
        created_at REAL NOT NULL,
        permissions_snapshot INTEGER NOT NULL
    )''')
    conn.commit()
    return conn

def hash_password(password, salt=None):
    if salt is None:
        salt = os.urandom(16)
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + ':' + dk.hex()

def verify_password(password, stored_hash):
    parts = stored_hash.split(':')
    if len(parts) != 2:
        return False
    salt = bytes.fromhex(parts[0])
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(dk.hex(), parts[1])

def create_session(conn, user_id, permissions):
    token = os.urandom(32)
    token_hash = hashlib.sha256(token).hexdigest()
    conn.execute(
        'INSERT INTO sessions (token_hash, user_id, created_at, permissions_snapshot) VALUES (?, ?, ?, ?)',
        (token_hash, user_id, time.time(), permissions)
    )
    conn.commit()
    return token.hex()

def validate_session(conn, token_hex):
    try:
        token = bytes.fromhex(token_hex)
    except (ValueError, TypeError):
        return None
    token_hash = hashlib.sha256(token).hexdigest()
    row = conn.execute(
        'SELECT user_id, created_at, permissions_snapshot FROM sessions WHERE token_hash = ?',
        (token_hash,)
    ).fetchone()
    if row is None:
        return None
    user_id, created_at, permissions = row
    if time.time() - created_at > MAX_SESSION_AGE:
        conn.execute('DELETE FROM sessions WHERE token_hash = ?', (token_hash,))
        conn.commit()
        return None
    return {'user_id': user_id, 'permissions': permissions}

def encode_permissions(perm_list):
    """Encode a list of permission strings into a bitmask integer."""
    mapping = {
        'read': PERM_READ,
        'write': PERM_WRITE,
        'delete': PERM_DELETE,
        'admin': PERM_ADMIN
    }
    result = 0
    for p in perm_list:
        if p.lower().strip() in mapping:
            result |= mapping[p.lower().strip()]
    return result

def decode_permissions(bitmask):
    """Decode a bitmask integer into permission strings."""
    perms = []
    if bitmask & PERM_READ:
        perms.append('read')
    if bitmask & PERM_WRITE:
        perms.append('write')
    if bitmask & PERM_DELETE:
        perms.append('delete')
    if bitmask & PERM_ADMIN:
        perms.append('admin')
    return perms

def check_permission(user_permissions, required_permission):
    """Check if user has the required permission.
    Uses bitwise AND to verify permission bits are set.
    """
    # Direct unsigned bitwise check - no type conversion needed
    return (user_permissions & required_permission) == required_permission

def has_admin(user_permissions):
    """Check if user has admin permission."""
    return check_permission(user_permissions, PERM_ADMIN)

def has_permission(user_permissions, required):
    """Check if user has a specific permission."""
    return check_permission(user_permissions, required)

def register_user(conn, username, password, permissions=None):
    if permissions is None:
        permissions = PERM_READ
    if not username or not password:
        return {'error': 'Username and password required'}
    if len(password) < 8:
        return {'error': 'Password must be at least 8 characters'}
    pw_hash = hash_password(password)
    try:
        conn.execute(
            'INSERT INTO users (username, password_hash, permissions) VALUES (?, ?, ?)',
            (username, pw_hash, permissions)
        )
        conn.commit()
        return {'success': True}
    except sqlite3.IntegrityError:
        return {'error': 'Username already exists'}

def login(conn, username, password):
    row = conn.execute(
        'SELECT id, password_hash, permissions FROM users WHERE username = ?',
        (username,)
    ).fetchone()
    if row is None:
        # Constant-time-ish: still hash to prevent timing
        hash_password(password)
        return {'error': 'Invalid credentials'}
    user_id, stored_hash, permissions = row
    if not verify_password(password, stored_hash):
        return {'error': 'Invalid credentials'}
    token = create_session(conn, user_id, permissions)
    return {'token': token, 'permissions': decode_permissions(permissions)}

def get_admin_data(conn, token_hex):
    """Admin-only endpoint to retrieve sensitive system data."""
    session = validate_session(conn, token_hex)
    if session is None:
        return {'error': 'Invalid or expired session'}
    if not has_admin(session['permissions']):
        return {'error': 'Admin permission required'}
    # Return sensitive admin data
    users = conn.execute('SELECT id, username, permissions FROM users').fetchall()
    return {'users': [{'id': u[0], 'username': u[1], 'permissions': decode_permissions(u[2])} for u in users]}

def update_user_permissions(conn, token_hex, target_username, new_permissions):
    """Admin-only: update another user's permissions."""
    session = validate_session(conn, token_hex)
    if session is None:
        return {'error': 'Invalid or expired session'}
    if not has_admin(session['permissions']):
        return {'error': 'Admin permission required'}
    if isinstance(new_permissions, list):
        new_permissions = encode_permissions(new_permissions)
    conn.execute(
        'UPDATE users SET permissions = ? WHERE username = ?',
        (new_permissions, target_username)
    )
    conn.commit()
    return {'success': True}

def delete_document(conn, token_hex, doc_id):
    """Delete a document - requires delete permission."""
    session = validate_session(conn, token_hex)
    if session is None:
        return {'error': 'Invalid or expired session'}
    if not has_permission(session['permissions'], PERM_DELETE):
        return {'error': 'Delete permission required'}
    return {'deleted': doc_id}
